package com.mohistmc.academy.network;
import com.mohistmc.academy.AcademyCraft;import com.mohistmc.academy.skill.*;import com.mohistmc.academy.skill.ability.teleporter.FlashingSessionManager;import io.netty.buffer.ByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.neoforged.neoforge.network.handling.IPayloadContext;
public record FlashingActionPacket(int action,long epoch)implements CustomPacketPayload{public static final int START=4,END=5,HOLD_BASE=8,RELEASE_BASE=12,CANCEL_BASE=16;public static final Type<FlashingActionPacket>TYPE=new Type<>(ResourceLocation.fromNamespaceAndPath(AcademyCraft.MODID,"flashing_action"));public static final StreamCodec<ByteBuf,FlashingActionPacket>STREAM_CODEC=StreamCodec.ofMember((p,b)->{b.writeByte(p.action);b.writeLong(p.epoch);},b->new FlashingActionPacket(b.readByte(),b.readLong()));public FlashingActionPacket(int action){this(action,com.mohistmc.academy.client.ClientPacketBridge.flashingEpoch());}public Type<? extends CustomPacketPayload>type(){return TYPE;}public static void handle(FlashingActionPacket x,IPayloadContext c){c.enqueueWork(()->{if(!(c.player()instanceof ServerPlayer p))return;long now=p.serverLevel().getGameTime();if(!PayloadRateLimiter.allow(p.getUUID(),"flashing",now,1,6))return;if(AbilityInterferenceService.isInterfered(p)){FlashingSessionManager.abort(p);AbilityInterferenceService.notifyBlocked(p);return;}PlayerAbilityData d=p.getData(AcademyAttachments.PLAYER_ABILITY);boolean abilityChanged=false;if(x.action==START)abilityChanged=FlashingSessionManager.start(p,d);else if(x.action==END)abilityChanged=FlashingSessionManager.end(p,d,x.epoch);else if(x.action>=HOLD_BASE&&x.action<HOLD_BASE+4)FlashingSessionManager.hold(p,d,x.action-HOLD_BASE,x.epoch);else if(x.action>=RELEASE_BASE&&x.action<RELEASE_BASE+4)abilityChanged=FlashingSessionManager.release(p,d,x.action-RELEASE_BASE,x.epoch);else if(x.action>=CANCEL_BASE&&x.action<CANCEL_BASE+4)FlashingSessionManager.cancelHold(p,x.action-CANCEL_BASE,x.epoch);if(abilityChanged)d.syncTo(p);});}}
